using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Threading;
namespace PZ3D {
 static class SaveEnvironmentsTests {
  static int checks;static Type serviceType,recordType;static bool failPreparation;static Action<object> duringPreparation;
  static void Check(bool condition,string message){if(!condition)throw new Exception("FAIL "+message);checks++;}
  static void Put(string path,string value){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,value,new UTF8Encoding(false));}
  static object Field(object row,string name){return row.GetType().GetField(name).GetValue(row);}
  static string Text(object row,string name){return (string)Field(row,name);}
  static object Call(object service,string name,params object[] args){try{return serviceType.GetMethods().Single(method=>method.Name==name&&method.GetParameters().Length==args.Length).Invoke(service,args);}catch(TargetInvocationException error){throw error.InnerException;}}
  static object Static(string name,params object[] args){var method=serviceType.GetMethod(name,BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic);Check(method!=null,"metadata ownership lookup exists without Engine construction");try{return method.Invoke(null,args);}catch(TargetInvocationException error){throw error.InnerException;}}
  static void Refuses(Action action,string reason){bool rejected=false;try{action();}catch(Exception){rejected=true;}Check(rejected,reason);}
  static object[] Rows(object list){return ((IEnumerable)list).Cast<object>().ToArray();}
  static void Prepare(object record){
   if(failPreparation)throw new IOException("Synthetic runtime preparation failure");
   Put(Path.Combine(Text(record,"RuntimeHome"),".zombie_buddy","config.json"),"{\"preload_mods\":{}}");
   Put(Path.Combine(Text(record,"GamePath"),"OrangeLauncherRuntime","startup","OrangeStartup.jar"),"pinned runtime");
   if(duringPreparation!=null)duringPreparation(record);
  }
  static Delegate Preparation(){return Delegate.CreateDelegate(typeof(Action<>).MakeGenericType(recordType),typeof(SaveEnvironmentsTests).GetMethod("Prepare",BindingFlags.Static|BindingFlags.NonPublic));}
  sealed class Fixture:IDisposable {
   internal readonly string Root,Game,User,Data,Save,First,Second;internal readonly Engine Engine;internal readonly object Service;
   internal Fixture(string parent,string name,int major=42,int overlap=0){
    Root=Path.Combine(parent,name);Game=overlap==2?Path.Combine(Root,"user","Game"):Path.Combine(Root,"steamapps","common","ProjectZomboid");User=overlap==1?Path.Combine(Game,"User"):Path.Combine(Root,"user");Data=Path.Combine(Root,"data");Save=Path.Combine(User,"Saves","Sandbox","Original");
    Put(Path.Combine(Game,"ProjectZomboid64.exe"),"game binary");Put(Path.Combine(Game,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");Put(Path.Combine(Game,"version.txt"),major==41?"41.78.16":"42.21.0");Put(Path.Combine(Game,"game-version.txt"),major==41?"41.78.16":"42.21.0");Put(Path.Combine(Game,"media","game.bin"),"game source bytes");Directory.CreateDirectory(Path.Combine(Game,"empty"));
    First=Path.Combine(Root,"steamapps","workshop","content","108600","100","mods","First");Second=Path.Combine(User,"mods","Second");
    string part=major==41?"":"42";
    Put(Path.Combine(First,part,"mod.info"),"id=First\nname=First\n");Put(Path.Combine(First,"common","media","texture.bin"),"common texture");Put(Path.Combine(First,"libs","plugin.jar"),"jar bytes");Put(Path.Combine(First,"libs","plugin.jar.zbs"),"signature bytes");
    Put(Path.Combine(Second,part,"mod.info"),"id=Second\nname=Second\nrequire=First\n");Put(Path.Combine(Second,part,"media","script.lua"),"return 'source'");
    Put(Path.Combine(User,"mods","default.txt"),"VERSION = 1,\nmods\n{\n mod = First,\n}\nmaps\n{\n}\n");
    Put(Path.Combine(Save,"mods.txt"),"VERSION = 1,\nmods\n{\n mod = First,\n mod = Second,\n}\nmaps\n{\n map = CustomMap,\n map = Muldraugh, KY,\n}\n");Put(Path.Combine(Save,"map.bin"),"original live world");
    Engine=new Engine(Game,User,Data,true,null,n=>new Process[0]);Service=Activator.CreateInstance(serviceType,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,new object[]{Engine},null);
   }
   internal object Preview(){return Call(Service,"Preview","Sandbox/Original");}
   internal object Create(string name="snapshot",Action<int,string> progress=null,CancellationToken? cancel=null){object plan=Preview();return Call(Service,"Create","Sandbox/Original",Path.Combine(Root,name),name,Text(plan,"stamp"),cancel??CancellationToken.None,progress,Preparation());}
   public void Dispose(){}
  }
  static Dictionary<string,byte[]> Tree(string root){return Directory.GetFiles(root,"*",SearchOption.AllDirectories).ToDictionary(p=>p.Substring(root.Length+1),File.ReadAllBytes,StringComparer.OrdinalIgnoreCase);}
  static bool EqualTree(Dictionary<string,byte[]> a,Dictionary<string,byte[]> b){return a.Count==b.Count&&a.All(p=>b.ContainsKey(p.Key)&&p.Value.SequenceEqual(b[p.Key]));}
  static void CopiesContentWithoutSaveMutation(string root){using(var f=new Fixture(root,"copy")){
   var saveBefore=Tree(f.Save);var preview=f.Preview();Check((bool)Field(preview,"ready")&&(int)Field(preview,"modCount")==2,"preview resolves every enabled mod source");Check((long)Field(preview,"gameBytes")>0&&(long)Field(preview,"modBytes")>0,"preview computes game and complete mod sizes");
   var phases=new List<string>();object record=f.Create("one",(v,t)=>phases.Add(t));string copied=Text(record,"GamePath");Check(File.ReadAllText(Path.Combine(copied,"media","game.bin"))=="game source bytes"&&Directory.Exists(Path.Combine(copied,"empty")),"full game and empty directories copied");
   Check(((string[])Field(record,"ModIds")).SequenceEqual(new[]{"First","Second"}),"captured save order is exact");Check(((string[])Field(record,"Maps")).SequenceEqual(new[]{"CustomMap","Muldraugh, KY"}),"captured map order is exact");
   object[] mappings=Rows(Field(record,"ModRoots"));string firstCopy=Text(mappings.Single(m=>Text(m,"SourceRoot")==f.First),"CopiedRoot");Check(File.ReadAllText(Path.Combine(firstCopy,"common","media","texture.bin"))=="common texture"&&File.ReadAllText(Path.Combine(firstCopy,"libs","plugin.jar.zbs"))=="signature bytes","whole source root preserves common assets Java libraries and signatures");
   Check(Path.GetFileName(firstCopy)=="First"&&Directory.GetParent(firstCopy).Name=="mods"&&Directory.GetParent(Directory.GetParent(firstCopy).FullName).Parent.FullName==Path.Combine(Text(record,"RootPath"),"mods"),"copied mod keeps original root name inside independent item/mods wrapper");
   Check(EqualTree(saveBefore,Tree(f.Save)),"snapshot creation leaves original save byte-identical");Check(!Directory.Exists(Path.Combine(f.Data,"save-backups"))&&!Directory.GetFiles(f.Root,"*.zip",SearchOption.AllDirectories).Any(),"creation never produces an automatic save archive");
   int gamePhase=phases.FindIndex(s=>s.StartsWith("复制游戏",StringComparison.Ordinal)),modPhase=phases.FindIndex(s=>s.StartsWith("复制模组",StringComparison.Ordinal));Check(gamePhase>=0&&modPhase>gamePhase,"game copy precedes mod copy");
   string id=Text(record,"Id");Directory.Delete(f.Game,true);Directory.Delete(f.First,true);Directory.Delete(f.Second,true);
   object loaded=Call(f.Service,"Get",id);Check(Text(loaded,"Id")==id&&Text(Call(f.Service,"Bound","Sandbox/Original"),"Id")==id,"metadata and binding remain readable after source deletion");Check(File.ReadAllText(Path.Combine(Text(loaded,"GamePath"),"media","game.bin"))=="game source bytes"&&File.ReadAllText(Path.Combine(firstCopy,"libs","plugin.jar"))=="jar bytes","deleting sources cannot change independent snapshot files");
   Check(Text(Static("FindOwned",f.Data,Text(record,"GamePath"),f.User),"Id")==id&&(bool)Static("OwnsUser",f.Data,Text(record,"GamePath"),f.User),"worker ownership accepts exact registered game and original live user after source deletion");Check(Static("FindOwned",f.Data,f.Game,f.User)==null&&!(bool)Static("OwnsUser",f.Data,Text(record,"GamePath"),Path.Combine(f.Root,"foreign-user")),"ordinary games and foreign user aliases are not snapshot ownership");
   Put(Path.Combine(Text(record,"RuntimeHome"),".zombie_buddy","config.json"),"runtime changed");Check(Call(f.Service,"Get",id)!=null,"mutable runtime state is outside immutable payload hash");
   Refuses(()=>Call(f.Service,"Bind","Sandbox/Other",id,Text(loaded,"Stamp")),"binding refuses a different original save");
  }}
  static void RetainsAndRebinds(string root){using(var f=new Fixture(root,"retention")){
   object first=f.Create("one");string firstId=Text(first,"Id");Put(Path.Combine(f.Game,"media","game.bin"),"new game version bytes");Put(Path.Combine(f.Second,"42","media","script.lua"),"new mod bytes");
   object updates=Call(f.Service,"CheckUpdates",firstId);Check((bool)Field(updates,"available")&&(bool)Field(updates,"changed"),"explicit check detects changed game or mod sources");
   object second=f.Create("two");Check(Text(Call(f.Service,"Bound","Sandbox/Original"),"Id")==Text(second,"Id"),"successful new snapshot becomes bound");Check(Rows(Call(f.Service,"List","Sandbox/Original")).Length==2&&Directory.Exists(Text(first,"RootPath")),"old working snapshot is retained");
   object latestFirst=Call(f.Service,"Get",firstId);Call(f.Service,"Bind","Sandbox/Original",firstId,Text(latestFirst,"Stamp"));Check(Text(Call(f.Service,"Bound","Sandbox/Original"),"Id")==firstId,"explicit switch can return to old snapshot");Refuses(()=>Call(f.Service,"Bind","Sandbox/Original",Text(second,"Id"),Text(latestFirst,"Stamp")),"stale binding stamp cannot overwrite a later selection");
  }}
  static void StartupMutableFilesDoNotSignalUpdates(string root){using(var f=new Fixture(root,"noise")){
   string startup=Path.Combine(f.Game,"OrangeLauncherRuntime","startup");string[] mutable={"session.properties","issues.txt","ownership.json"};foreach(string name in mutable)Put(Path.Combine(startup,name),"first mutable "+name);string jar=Path.Combine(startup,"OrangeStartup.jar");Put(jar,"original startup JAR");duringPreparation=record=>{foreach(string name in mutable)Put(Path.Combine(startup,name),"changed during preparation "+name);};object snapshot;try{snapshot=f.Create();}finally{duringPreparation=null;}string id=Text(snapshot,"Id");Check(!Rows(Field(snapshot,"GameSourceFiles")).Any(file=>mutable.Any(name=>Text(file,"Path")=="OrangeLauncherRuntime/startup/"+name)),"source capture excludes exactly the three mutable startup state files");Check(mutable.All(name=>!File.Exists(Path.Combine(Text(snapshot,"GamePath"),"OrangeLauncherRuntime","startup",name))),"copy does not carry stale startup session, issue or ownership files");
   foreach(string name in mutable){Put(Path.Combine(startup,name),"another launch changed "+name);var updates=Call(f.Service,"CheckUpdates",id);Check((bool)Field(updates,"available")&&!(bool)Field(updates,"gameChanged")&&!(bool)Field(updates,"changed"),"mutable startup "+name+" changes do not signal a game update");}
   foreach(string path in new[]{jar,Path.Combine(f.Game,"ProjectZomboid64.json"),Path.Combine(f.Game,"media","game.bin")}){byte[] before=File.ReadAllBytes(path);DateTime written=File.GetLastWriteTimeUtc(path);Put(path,path.EndsWith(".json",StringComparison.OrdinalIgnoreCase)?"{\"vmArgs\":[\"-Xmx5g\"]}":"real changed payload");var updates=Call(f.Service,"CheckUpdates",id);Check((bool)Field(updates,"available")&&(bool)Field(updates,"gameChanged"),"startup JAR, launch JSON and real game content each remain update evidence: "+Path.GetFileName(path));File.WriteAllBytes(path,before);File.SetLastWriteTimeUtc(path,written);}
  }}
  static void UnbindRetainsHistory(string root){using(var f=new Fixture(root,"unbind")){
   Check(serviceType.GetMethod("BindingStamp")!=null&&serviceType.GetMethod("Unbind")!=null,"lightweight binding and unbind APIs exist");object record=f.Create("one");string id=Text(record,"Id"),stamp=(string)Call(f.Service,"BindingStamp","Sandbox/Original");Directory.Delete(f.Game,true);Directory.Delete(f.First,true);Directory.Delete(f.Second,true);
   string next=(string)Call(f.Service,"Unbind","Sandbox/Original",stamp);Check(Call(f.Service,"Bound","Sandbox/Original")==null&&next!=stamp,"using current environment removes only the binding and advances stamp");Check(Rows(Call(f.Service,"List","Sandbox/Original")).Length==1&&Directory.Exists(Text(record,"RootPath")),"unbind retains snapshot history and payload after source deletion");Refuses(()=>Call(f.Service,"Unbind","Sandbox/Original",stamp),"stale unbind cannot override later user choices");Call(f.Service,"Bind","Sandbox/Original",id,next);Check(Text(Call(f.Service,"Bound","Sandbox/Original"),"Id")==id,"retained snapshot can be rebound without live source game");
   Put(LaunchProfiles.Journal(f.Engine),"pending launch");Refuses(()=>Call(f.Service,"Unbind","Sandbox/Original",(string)Call(f.Service,"BindingStamp","Sandbox/Original")),"unbind refuses an unfinished launch session");
   File.Delete(LaunchProfiles.Journal(f.Engine));string token=DlssInstaller.Hash(Encoding.UTF8.GetBytes(Path.GetFullPath(Text(record,"GamePath")).ToUpperInvariant()+"|"+Path.GetFullPath(f.User).ToUpperInvariant()));Put(Path.Combine(f.Data,"launch-sessions",token+".json"),"snapshot pending launch");Refuses(()=>Call(f.Service,"Unbind","Sandbox/Original",(string)Call(f.Service,"BindingStamp","Sandbox/Original")),"unbind refuses the currently bound snapshot session without constructing its Engine");
  }}
  static void FailsSafely(string root){using(var f=new Fixture(root,"failures")){
   object prior=f.Create("prior");string old=Text(prior,"Id");
   failPreparation=true;try{Refuses(()=>f.Create("prepare-failed"),"runtime preparation failure prevents snapshot registration");}finally{failPreparation=false;}
   Check(!Directory.Exists(Path.Combine(f.Root,"prepare-failed"))&&Text(Call(f.Service,"Bound","Sandbox/Original"),"Id")==old,"failed preparation removes owned destination and retains old binding");
   duringPreparation=record=>Put(Path.Combine(f.Game,"late-update.bin"),"late Steam update");try{Refuses(()=>f.Create("late-change"),"source change during runtime preparation is rejected");}finally{duringPreparation=null;}
   Check(!Directory.Exists(Path.Combine(f.Root,"late-change"))&&Text(Call(f.Service,"Bound","Sandbox/Original"),"Id")==old,"late source mutation preserves previous binding and removes unregistered copy");
   duringPreparation=record=>{object mapping=Rows(Field(record,"ModRoots")).Single(row=>Text(row,"SourceRoot")==f.First);Put(Path.Combine(Text(mapping,"CopiedRoot"),"libs","plugin.jar"),"callback changed payload");};try{Refuses(()=>f.Create("modified-payload"),"runtime preparation cannot rewrite captured mod bytes");}finally{duringPreparation=null;}
   var cancel=new CancellationTokenSource();Refuses(()=>f.Create("cancelled",(v,t)=>cancel.Cancel(),cancel.Token),"streaming cancellation prevents publication");Check(!Directory.Exists(Path.Combine(f.Root,"cancelled"))&&!Directory.GetDirectories(f.Root,"*.partial-*").Any(),"cancel removes only owned staging");
   bool changed=false;Refuses(()=>f.Create("changed",(v,t)=>{if(!changed){changed=true;Put(Path.Combine(f.Game,"new-file.bin"),"Steam update");}}),"source membership change during copy is rejected");Check(!Directory.Exists(Path.Combine(f.Root,"changed"))&&Text(Call(f.Service,"Bound","Sandbox/Original"),"Id")==old,"source mutation leaves old working binding intact");
   object plan=f.Preview();Put(Path.Combine(f.First,"libs","another.bin"),"new content");Refuses(()=>Call(f.Service,"Create","Sandbox/Original",Path.Combine(f.Root,"stale"),"stale",Text(plan,"stamp"),CancellationToken.None,null,Preparation()),"stale preview cannot copy changed inputs");
   bool occupied=false;Refuses(()=>f.Create("occupied",(v,t)=>{if(!occupied){occupied=true;Put(Path.Combine(f.Root,"occupied","foreign.txt"),"foreign destination");}}),"destination created by another task cannot be overwritten");Check(File.ReadAllText(Path.Combine(f.Root,"occupied","foreign.txt"))=="foreign destination","failed creation preserves foreign destination bytes");
   Put(Path.Combine(f.Second,"42","mod.info"),"id=Second\nrequire=NotEnabled\n");Check(!(bool)Field(f.Preview(),"ready"),"missing enabled dependency blocks complete capture");Put(Path.Combine(f.Second,"42","mod.info"),"id=Second\nrequire=First\n");
   Put(Path.Combine(f.User,"mods","Duplicate","42","mod.info"),"id=First\n");Check(!(bool)Field(f.Preview(),"ready"),"ambiguous enabled ID blocks complete capture");Directory.Delete(Path.Combine(f.User,"mods","Duplicate"),true);
   Directory.Delete(f.First,true);Check(!(bool)Field(f.Preview(),"ready"),"missing selected source blocks capture");Check(Rows(Call(f.Service,"List",(object)null)).Length==1,"failed operations never add partial records");
  }}
  static void ValidatesInputAndPayload(string root){using(var f=new Fixture(root,"validation",41)){
   Refuses(()=>Call(f.Service,"Preview","../escape"),"save IDs cannot escape original user root");object plan=f.Preview();Check((bool)Field(plan,"ready"),"B41 flat mod layouts resolve without B42-only fallback");
   Refuses(()=>Call(f.Service,"Create","Sandbox/Original",Path.Combine(f.Save,"inside"),"bad",Text(plan,"stamp"),CancellationToken.None,null,Preparation()),"destination cannot overlap original save or user files");Refuses(()=>Call(f.Service,"Create","Sandbox/Original",Path.Combine(f.Root,"no-runtime"),"bad",Text(plan,"stamp"),CancellationToken.None,null,null),"production creation requires explicit runtime preparation");
   object record=f.Create("valid");string manifest=Text(record,"ManifestPath");File.AppendAllText(manifest," ");Refuses(()=>Call(f.Service,"Get",Text(record,"Id")),"immutable manifest tampering is detected without touching live sources");
   Refuses(()=>Static("FindOwned",f.Data,Text(record,"GamePath"),f.User),"worker lookup fails closed for registered corrupted manifest");Check(!(bool)Static("OwnsUser",f.Data,Text(record,"GamePath"),f.User),"worker ownership refuses corrupted registered payload metadata");
  }}
  static void CapturesPreloadedJava(string root){using(var f=new Fixture(root,"preloads")){
   string javaRoot=Path.Combine(f.Game,"mods","Preloaded"),info=Path.Combine(javaRoot,"42","mod.info"),jar=Path.Combine(javaRoot,"common","lib","preload.jar"),home=Path.Combine(f.Root,"java-home");Put(info,"id=Preloaded\njavaJarFile=../common/lib/preload.jar\njavaPkgName=example.preload\n");Put(jar,"preloaded Java bytes");Put(jar+".zbs","preloaded signature");
   var serializer=new System.Web.Script.Serialization.JavaScriptSerializer();Put(Path.Combine(f.Game,"ProjectZomboid64.json"),serializer.Serialize(new{vmArgs=new[]{"-agentlib:zbNative","-Duser.home="+home}}));Put(Path.Combine(home,".zombie_buddy","config.json"),serializer.Serialize(new{preload_mods=new Dictionary<string,object>{{"Preloaded",new{infPath=info,jarPath=jar}}}}));
   object record=f.Create("with-preload");Check(((string[])Field(record,"ModIds")).SequenceEqual(new[]{"First","Second"})&&((string[])Field(record,"PreloadModIds")).SequenceEqual(new[]{"Preloaded"}),"preloaded Java is captured separately without changing save mod order");var mapping=Rows(Field(record,"ModRoots")).Single(row=>Text(row,"SourceRoot")==javaRoot);Check(File.ReadAllText(Path.Combine(Text(mapping,"CopiedRoot"),"common","lib","preload.jar"))=="preloaded Java bytes","preloaded game-local Java files keep complete relative layout");
   Put(Path.Combine(f.Game,"ProjectZomboid64.json"),"{\"vmArgs\":[\"-javaagent:C:/outside/foreign.jar\"]}");Check(!(bool)Field(f.Preview(),"ready"),"unowned external Java agent prevents an incomplete snapshot");
  }}
  static void RejectsOverlappingSourceUser(string root){foreach(int overlap in new[]{1,2})using(var f=new Fixture(root,"overlap-"+overlap,42,overlap)){
   var before=Tree(f.Root);var directories=Directory.GetDirectories(f.Root,"*",SearchOption.AllDirectories);var plan=f.Preview();Check(!(bool)Field(plan,"ready"),"preview refuses game and original user trees that overlap");
   Refuses(()=>Call(f.Service,"Create","Sandbox/Original",Path.Combine(f.Root,"snapshot"),"snapshot",new string('a',64),CancellationToken.None,null,Preparation()),"overlapping original game/user roots fail before snapshot copying");
   Check(EqualTree(before,Tree(f.Root))&&directories.OrderBy(path=>path).SequenceEqual(Directory.GetDirectories(f.Root,"*",SearchOption.AllDirectories).OrderBy(path=>path)),"overlap preview and creation write no file or directory, including original saves");
  }}
  static void SharedWorkshopWrapper(string root){using(var f=new Fixture(root,"shared-item")){
   string sibling=Path.Combine(Path.GetDirectoryName(f.First),"Sibling");Put(Path.Combine(sibling,"42","mod.info"),"id=Sibling\nname=Same Workshop sibling\n");Put(Path.Combine(sibling,"common","payload.bin"),"sibling bytes");Put(Path.Combine(f.Save,"mods.txt"),File.ReadAllText(Path.Combine(f.Save,"mods.txt")).Replace(" mod = First,"," mod = First,\n mod = Sibling,"));var record=f.Create();var roots=Rows(Field(record,"ModRoots"));var first=roots.Single(row=>Text(row,"SourceRoot")==f.First);var second=roots.Single(row=>Text(row,"SourceRoot")==sibling);string firstWrapper=Directory.GetParent(Directory.GetParent(Text(first,"CopiedRoot")).FullName).FullName,secondWrapper=Directory.GetParent(Directory.GetParent(Text(second,"CopiedRoot")).FullName).FullName;
   Check(firstWrapper==secondWrapper&&Directory.Exists(Path.Combine(firstWrapper,"mods","First"))&&File.ReadAllText(Path.Combine(firstWrapper,"mods","Sibling","common","payload.bin"))=="sibling bytes","one actual Workshop item shares a wrapper containing every captured child mod root");var frozen=new Engine(Text(record,"GamePath"),f.User,f.Data,true);Check(InstallWorkflow.Source(frozen,100)==firstWrapper,"item lookup resolves its complete frozen multi-mod wrapper");var local=frozen.FrozenEnvironment.ModRoots.Single(row=>row.SourceRoot==f.Second);local.WorkshopId="100";Refuses(()=>InstallWorkflow.Source(frozen,100),"same numeric Workshop ID from distinct physical wrappers is refused instead of selecting the first");
  }}
  public static int Main(){string root=null;try{serviceType=typeof(Engine).Assembly.GetType("PZ3D.SaveEnvironments");Check(serviceType!=null,"save environment storage backend exists");recordType=typeof(Engine).Assembly.GetType("PZ3D.SaveEnvironmentRecord");Check(recordType!=null,"snapshot metadata type exists");root=Path.Combine(LauncherTestPaths.Root,"save-environments-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);StartupMutableFilesDoNotSignalUpdates(root);SharedWorkshopWrapper(root);RejectsOverlappingSourceUser(root);CopiesContentWithoutSaveMutation(root);RetainsAndRebinds(root);UnbindRetainsHistory(root);FailsSafely(root);ValidatesInputAndPayload(root);CapturesPreloadedJava(root);Console.WriteLine("SaveEnvironments PASS: "+checks+" assertions");return 0;}catch(Exception error){Console.WriteLine(error);return 1;}finally{if(root!=null){string full=Path.GetFullPath(root),parent=Path.GetFullPath(LauncherTestPaths.Root)+Path.DirectorySeparatorChar;if(!full.StartsWith(parent,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(full).StartsWith("save-environments-",StringComparison.Ordinal))throw new IOException("Unsafe fixture cleanup");if(Directory.Exists(full))Directory.Delete(full,true);}}}
 }
